{
  "notes": [
    { "character": "沈知微", "kind": "background", "text": "前世死在十九岁那年的腊月，欠下三百两银子的赌债", "quote": "前世她心软过，结果连命都赔了进去。" },
    { "character": "沈知微", "kind": "personality", "text": "只算自己的账，谁的情都不欠，谁的亏都不吃", "quote": "这一世，她只算自己的账。谁的情都不欠，谁的亏都不吃。" },
    { "character": "沈知微", "kind": "goal", "text": "把家底摸清，花在刀刃上", "quote": "她还有二十七天。院子里传来二叔沈承业的嗓门。" },
    { "character": "沈若兰", "kind": "relationship", "text": "是沈知微的妹妹", "quote": "门外忽然响起一阵轻快的脚步声，接着是一个娇滴滴的声音：\"堂姐醒了没有？我给你送姜汤来了。\"是二叔的女儿，沈若兰。" }
  ]}

{
  "summary": "沈知微在周记当铺被冻醒，回忆起前世的不幸遭遇。",
  "tension": 3,
  "emotions": ["heartache", "tension"],
  "hook": {

  "present": true,
  "quote": "门外忽然响起一阵轻快的脚步声，接着是一个娇滴滴的声音：‘堂姐醒了没有？我给你送姜汤来了。’是二叔的女儿，沈若兰。"
}
  , "beats": [
    {
      "character": "沈知微",
      "action": "回忆前世的不幸遭遇",
      "quote": "她记得清清楚楚：二叔在城南的长乐赌坊欠了三百两银子，赌坊的刘三放过话，年前还不上，就剁他一只手。前世，正是这个月底，二叔把沈家老宅连同绸缎铺子一起卖给了陆家，换来的银子一半填了赌债。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈若兰",
      "action": "给沈知微送姜汤",
      "quote": "门外忽然响起一阵轻快的脚步声，接着是一个娇滴滴的声音：‘堂姐醒了没有？我给你送姜汤来了。’是二叔的女儿，沈若兰。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈知微",
      "action": "确认自己不是在雪地里等了一夜",
      "quote": "她盯着帐顶那块洗得发白的补丁看了很久，才确认自己不是躺在周记当铺门外的雪地里。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈知微",
      "action": "摸清家底并决定如何花钱",
      "quote": "她把这一世的家底摸了一遍：枕头底下三十七文铜钱，一支母亲留下的银簪，还有贴身挂着的那块玉佩。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈知微",
      "action": "决定这一世只算自己的账",
      "quote": "她把玉佩塞回衣领里，在心里给自己定了规矩：这一世，她只算自己的账。谁的情都不欠，谁的亏都不吃，每一文钱都要花在刀刃上。",
      "hostile": false,
      "target": "",
      "cost": ""
    },
    {
      "character": "沈知微",
      "action": "确认父亲下葬情况",
      "quote": "父亲是昨天下葬的。",
      "hostile": false,
      "target": "",
      "cost": ""
    }
  ],
  "setups": [
    {
      "text": "她盯着帐顶那块洗得发白的补丁看了很久，才确认自己不是躺在周记当铺门外的雪地里。",
      "quote": "她盯着帐顶那块洗得发白的补丁看了很久，才确认自己不是躺在周记当铺门外的雪地里。"
    },
    {
      "text": "父亲是昨天下葬的。",
      "quote": "父亲是昨天下葬的。"
    }
  ]
}

{
    "notes": [
        {
            "character": "沈知微",
            "kind": "background",
            "text": "前世在城东的周记当铺咽气。",
            "quote": "天刚亮，沈知微就揣着那支银簪出了门。"
        },
        {
            "character": "沈知微",
            "kind": "personality",
            "text": "心地善良，乐于助人。",
            "quote": "路过桥头时，一个七八岁的小乞丐缩在石狮子后面，冻得嘴唇发紫，怀里抱着个缺了口的破碗。他没敢伸手，只是怯怯地看了她一眼。"
        },
        {
            "character": "沈知微",
            "kind": "goal",
            "text": "撑过接下来的三天。",
            "quote": "剩下的十七文，只够她再撑三天。"
        },
        {
            "character": "顾晏",
            "kind": "knowledge",
            "text": "正月里盐价要跌一半。",
            "quote": "沈知微转身出门，没有回头。她说过：‘顾少东家，正月里盐价要跌一半。手里有盐引的，最好年前出手。’"
        }
    ]
}

{
  "summary": "沈知微施舍给小乞丐三十七文后，前往周记当铺向顾晏借钱。",
  "tension": 3,
  "emotions": ["heartache", "tension"],
  "hook": {

  "present": true,
  "quote": "顾少东家，正月里盐价要跌一半。手里有盐引的，最好年前出手。"
}
  , "beats":[
    {"character":"沈知微","action":"把怀里的三十七文数出二十文倒进小乞丐的碗里","quote":"天刚亮，沈知微就揣着那支银簪出了门。路过桥头时，一个七八岁的小乞丐缩在石狮子后面，冻得嘴唇发紫，怀里抱着个缺了口的破碗。他没敢伸手，只是怯怯地看了她一眼。沈知微心里一软，把怀里的三十七文数出二十文，全倒进了他的碗里。","hostile":false,"target":"小乞丐","cost":"无"},
    {"character":"顾晏","action":"少东家顾晏坐在里间看账，听伙计报了价后抬头看了沈知微一眼","quote":"路过桥头时，一个七八岁的小乞丐缩在石狮子后面，冻得嘴唇发紫，怀里抱着个缺了口的破碗。他没敢伸手，只是怯怯地看了她一眼。周记当铺的少东家顾晏正坐在里间看账，听伙计报了价，抬头看了她一眼。","hostile":false,"target":"沈知微","cost":"无"},
    {"character":"沈知微","action":"沈知微接过银子，并压低声音告诉顾晏关于盐价的信息","quote":"沈知微接过银子，压低声音说了一句：“顾少东家，正月里盐价要跌一半。手里有盐引的，最好年前出手。”前世，正月初十盐价暴跌，临川好几家商号一夜之间倒了，周记也赔进去一大笔。这件事，她记了两辈子。","hostile":false,"target":"顾晏","cost":"无"},
    {"character":"顾晏","action":"顾晏停下动作询问沈知微关于盐价的信息来源","quote":"顾晏的手指在账本上停了停：“沈姑娘从哪里听来的？”，“你信，就当是我还你的利息；不信，就当我没说。","hostile":false,"target":"沈知微","cost":"无"},
    {"character":"沈知微","action":"沈知微转身离开周记当铺","quote":"她转身出门，没有回头。顾晏一直看着她的背影，直到伙计喊了他两声，才低下头去。","hostile":false,"target":"顾晏","cost":"无"},
    {"character":"小乞丐","action":"小乞丐接过沈知微给的银子后愣住了","quote":"小乞丐愣住了，连谢都忘了说。","hostile":false,"target":"小乞丐","cost":"无"}
  ]
, "setups":[
    {"text":"前世她咽气的地方是城东的周记当铺。","quote":"天刚亮，沈知微就揣着那支银簪出了门。路过桥头时，一个七八岁的小乞丐缩在石狮子后面，冻得嘴唇发紫，怀里抱着个缺了口的破碗。他没敢伸手，只是怯怯地看了她一眼。周记当铺的少东家顾晏正坐在里间看账，听伙计报了价，抬头看了她一眼。"}
  ]
}

{
    "notes": [
        {
            "character": "沈若兰",
            "kind": "personality",
            "text": "看人不顺眼就来气。",
            "quote": "她和这个堂姐没有过节，堂姐也从没碍过她什么事，她就是看她不顺眼。"
        },
        {
            "character": "沈知微",
            "kind": "wound",
            "text": "梦里全是前世的雪。",
            "quote": "她裹着棉被在床上发了一夜的烧，梦里全是前世的雪。"
        }
    ]
}

