  "notes": [
    { "character": "沈知微", "kind": "knowledge", "text": "算清楚用五十文钱换老宅的下落这笔买卖不亏", "quote": "她算得很清楚：小六每天给二叔端茶倒水，二叔把地契藏在哪儿，他最有可能知道。" },
    { "character": "沈知微", "kind": "wound", "text": "老宅的下落", "quote": "用五十文钱换老宅的下落这笔买卖不亏" },
